export default function TechMarquee() {
  const doubled = [...techStack, ...techStack];

  return (
    <section className="py-10 sm:py-14 lg:py-16 overflow-hidden border-y border-border bg-bg">
      <div className="relative">
        <motion.div
          className="flex gap-4 sm:gap-6 whitespace-nowrap"
          animate={{ x: ["0%", "-50%"] }}
          transition={{
            x: {
              repeat: Infinity,
              repeatType: "loop",
              duration: 30,
              ease: "linear",
            },
          }}
        >
          {doubled.map((tech, i) => (
            <div
              key={`${tech.name}-${i}`}
              className="inline-flex items-center gap-2.5 px-5 py-2.5 sm:px-6 sm:py-3 rounded-full border bg-bg text-sm sm:text-base font-medium transition-all duration-300 cursor-default shrink-0 hover:shadow-md"
              style={{
                borderColor: `${tech.color}40`,
                color: tech.color,
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = tech.color;
                e.currentTarget.style.boxShadow = `0 4px 14px ${tech.color}20`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = `${tech.color}40`;
                e.currentTarget.style.boxShadow = "none";
              }}
            >
              <span style={{ color: tech.color }}>{tech.icon}</span>
              <span className="text-text-primary">{tech.name}</span>
            </div>
          ))}
        </motion.div>

        <div className="absolute top-0 left-0 w-16 sm:w-24 h-full bg-gradient-to-r from-bg to-transparent pointer-events-none z-10" />
        <div className="absolute top-0 right-0 w-16 sm:w-24 h-full bg-gradient-to-l from-bg to-transparent pointer-events-none z-10" />
      </div>
    </section>
  );
}
